import { createHash } from "node:crypto";

const FORBIDDEN_KEYS = new Set([
  "rawprompt",
  "prompt",
  "messages",
  "body",
  "authorization",
  "apikey",
  "headers",
]);

const SECRET_VALUE_PATTERNS = [
  /\bsk-[A-Za-z0-9_-]{8,}\b/,
  /\bphc_[A-Za-z0-9_-]{8,}\b/,
  /\bghp_[A-Za-z0-9_-]{8,}\b/,
  /\bAKIA[0-9A-Z]{16}\b/,
  /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/,
];

const REPRODUCER_KINDS = new Set(["scenario", "route", "command-id"]);

function isObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function normalizedKey(key) {
  return String(key).toLowerCase().replace(/[-_]/g, "");
}

function findUnsafeContent(value, location = "trace") {
  if (typeof value === "string") {
    for (const pattern of SECRET_VALUE_PATTERNS) {
      if (pattern.test(value)) {
        return { location, reason: "credential-pattern" };
      }
    }
    return null;
  }

  if (Array.isArray(value)) {
    for (let index = 0; index < value.length; index += 1) {
      const found = findUnsafeContent(value[index], `${location}[${index}]`);
      if (found) return found;
    }
    return null;
  }

  if (isObject(value)) {
    for (const [key, child] of Object.entries(value)) {
      const normalized = normalizedKey(key);
      if (FORBIDDEN_KEYS.has(normalized)) {
        return { location: `${location}.${key}`, reason: `forbidden-field:${normalized}` };
      }
      const found = findUnsafeContent(child, `${location}.${key}`);
      if (found) return found;
    }
  }

  return null;
}

function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
  if (isObject(value)) {
    return `{${Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

function sha256(value) {
  return createHash("sha256").update(value, "utf8").digest("hex");
}

function boundedString(value, maxLength, field) {
  if (typeof value !== "string" || value.length === 0 || value.length > maxLength) {
    throw new TypeError(`${field} must be a non-empty string of at most ${maxLength} characters`);
  }
  return value;
}

function validateReproducer(reproducer) {
  if (!isObject(reproducer)) throw new TypeError("reproducer must be an object");
  const { kind } = reproducer;
  if (!REPRODUCER_KINDS.has(kind)) {
    throw new TypeError("reproducer.kind must be scenario, route, or command-id");
  }
  if (kind === "scenario") {
    return {
      kind,
      scenarioId: boundedString(reproducer.scenarioId, 256, "reproducer.scenarioId"),
    };
  }
  if (kind === "route") {
    return {
      kind,
      routeId: boundedString(reproducer.routeId, 256, "reproducer.routeId"),
      method: boundedString(reproducer.method, 16, "reproducer.method").toUpperCase(),
    };
  }
  return {
    kind,
    commandId: boundedString(reproducer.commandId, 256, "reproducer.commandId"),
  };
}

function validateSelector(selector) {
  if (!isObject(selector)) throw new TypeError("selector must be an object");
  const runId = boundedString(selector.runId, 256, "selector.runId");
  if (!Number.isSafeInteger(selector.attempt) || selector.attempt < 1) {
    throw new TypeError("selector.attempt must be a positive safe integer");
  }
  return { runId, attempt: selector.attempt };
}

function traceStatus(trace) {
  return String(trace.status ?? trace.outcome ?? "").toLowerCase();
}

function isFailure(trace) {
  const status = traceStatus(trace);
  return status === "failed" || status === "failure" || status === "error";
}

function isPassOutcome(trace) {
  const status = traceStatus(trace);
  return ["passed", "success", "successful", "rejected", "cancelled", "canceled"].includes(status);
}

function expectedOutcome(trace) {
  return isFailure(trace) ? "fail" : "pass";
}

function sampleId(trace, selector) {
  return `trace-${selector.runId}-${selector.attempt}`;
}

/**
 * Convert one explicitly selected trace. The trace must already be sanitized.
 * This function performs no I/O and never mutates the supplied trace.
 */
export function traceToEvalSample(trace, options = {}) {
  if (!isObject(trace)) throw new TypeError("trace must be an object");
  const unsafe = findUnsafeContent(trace);
  if (unsafe) {
    const error = new Error(`trace rejected: ${unsafe.reason} at ${unsafe.location}`);
    error.code = "UNSANITIZED_TRACE";
    error.diagnostic = unsafe;
    throw error;
  }

  const selector = validateSelector(trace.selector ?? options.selector);
  const reproducer = validateReproducer(trace.reproducer ?? options.reproducer);
  const outcome = expectedOutcome(trace);
  const beforeFix = outcome === "fail" ? "fail" : "pass";
  const afterFix = "pass";
  const digestInput = {
    sampleId: sampleId(trace, selector),
    selector,
    reproducer,
    beforeFix,
    afterFix,
    evidence: trace.evidence ?? null,
  };
  const digest = sha256(canonicalJson(digestInput));

  return {
    schemaVersion: 1,
    id: sampleId(trace, selector),
    source: {
      runId: selector.runId,
      attempt: selector.attempt,
    },
    reproducer,
    selector,
    expectations: {
      "before-fix": beforeFix,
      "after-fix": afterFix,
    },
    digest,
    digestAlgorithm: "sha256",
  };
}

/**
 * Explicitly convert selected traces. `selectedTraceIds` is required and is
 * matched against trace.id (or trace.traceId). No discovery or background work
 * is performed. Every rejected trace produces its own diagnostic entry.
 */
export function convertSelectedTracesToEvalSamples(traces, options = {}) {
  if (!Array.isArray(traces)) throw new TypeError("traces must be an array");
  if (!Array.isArray(options.selectedTraceIds)) {
    throw new TypeError("options.selectedTraceIds must be an array");
  }

  const selected = new Set(options.selectedTraceIds.map(String));
  const samples = [];
  const diagnostics = [];
  for (const trace of traces) {
    const id = trace && (trace.id ?? trace.traceId);
    if (id === undefined || !selected.has(String(id))) continue;
    try {
      samples.push(traceToEvalSample(trace, options));
    } catch (error) {
      diagnostics.push({
        traceId: String(id),
        code: error.code ?? "INVALID_TRACE",
        message: error.message,
      });
    }
  }

  return { samples, diagnostics };
}

export function assertSanitizedTrace(trace) {
  const unsafe = findUnsafeContent(trace);
  if (unsafe) {
    const error = new Error(`trace rejected: ${unsafe.reason} at ${unsafe.location}`);
    error.code = "UNSANITIZED_TRACE";
    error.diagnostic = unsafe;
    throw error;
  }
  return true;
n}

export function isRawCredentialPattern(value) {
  return typeof value === "string" && SECRET_VALUE_PATTERNS.some((pattern) => pattern.test(value));
}

export default convertSelectedTracesToEvalSamples;

export type Reproducer =
  | { kind: "scenario"; scenarioId: string }
  | { kind: "route"; routeId: string; method: string }
  | { kind: "command-id"; commandId: string };

export interface TraceSelector {
  runId: string;
  attempt: number;
}

export interface Trace {
  id?: string;
  traceId?: string;
  status?: string;
  outcome?: string;
  selector: TraceSelector;
  reproducer: Reproducer;
  evidence?: unknown;
  [key: string]: unknown;
}

export interface EvalSample {
  schemaVersion: 1;
  id: string;
  source: { runId: string; attempt: number };
  reproducer: Reproducer;
  selector: TraceSelector;
  expectations: { "before-fix": "fail" | "pass"; "after-fix": "pass" };
  digest: string;
  digestAlgorithm: "sha256";
}

export interface TraceDiagnostic {
  traceId: string;
  code: string;
  message: string;
}

export interface ConversionResult {
  samples: EvalSample[];
  diagnostics: TraceDiagnostic[];
}

export interface ConversionOptions {
  selectedTraceIds: string[];
  selector?: TraceSelector;
  reproducer?: Reproducer;
}

export function traceToEvalSample(trace: Trace, options?: ConversionOptions): EvalSample;
export function convertSelectedTracesToEvalSamples(traces: Trace[], options: ConversionOptions): ConversionResult;
export function assertSanitizedTrace(trace: unknown): boolean;
export function isRawCredentialPattern(value: unknown): boolean;

export default convertSelectedTracesToEvalSamples;

