      method: boundedString(reproducer.method, 16, "reproducer.method").toUpperCase(),
    };
  }
  return {
    kind,
    commandId: boundedString(reproducer.commandId, 256, "reproducer.commandId"),
  };
}

function validateSelector(selector) {
  if (!isObject(selector)) throw new TypeError("selector must be an object");
  const runId = boundedString(selector.runId, 256, "selector.runId");
  if (!Number.isSafeInteger(selector.attempt) || selector.attempt < 1) {
    throw new TypeError("selector.attempt must be a positive safe integer");
  }
  return { runId, attempt: selector.attempt };
}

function traceStatus(trace) {
  return String(trace.status ?? trace.outcome ?? "").toLowerCase();
}

function isFailure(trace) {
  const status = traceStatus(trace);
  return status === "failed" || status === "failure" || status === "error";
}

function isPassOutcome(trace) {
  const status = traceStatus(trace);
  return ["passed", "success", "successful", "rejected", "cancelled", "canceled"].includes(status);
}

function expectedOutcome(trace) {
  return isFailure(trace) ? "fail" : "pass";
}

function sampleId(trace, selector) {
  return `trace-${selector.runId}-${selector.attempt}`;
}

/**
 * Convert one explicitly selected trace. The trace must already be sanitized.
 * This function performs no I/O and never mutates the supplied trace.
 */
export function traceToEvalSample(trace, options = {}) {
  if (!isObject(trace)) throw new TypeError("trace must be an object");
  const unsafe = findUnsafeContent(trace);
  if (unsafe) {
    const error = new Error(`trace rejected: ${unsafe.reason} at ${unsafe.location}`);
    error.code = "UNSANITIZED_TRACE";
    error.diagnostic = unsafe;
    throw error;
  }

  const selector = validateSelector(trace.selector ?? options.selector);
  const reproducer = validateReproducer(trace.reproducer ?? options.reproducer);
  const outcome = expectedOutcome(trace);
  const beforeFix = outcome === "fail" ? "fail" : "pass";
  const afterFix = "pass";
  const digestInput = {
    sampleId: sampleId(trace, selector),
    selector,
    reproducer,
    beforeFix,
    afterFix,
    evidence: trace.evidence ?? null,
  };
  const digest = sha256(canonicalJson(digestInput));

  return {
    schemaVersion: 1,
    id: sampleId(trace, selector),
    source: {
      runId: selector.runId,
      attempt: selector.attempt,
    },
    reproducer,
    selector,
    expectations: {
      "before-fix": beforeFix,
      "after-fix": afterFix,
    },
    digest,
    digestAlgorithm: "sha256",
  };
}

/**
 * Explicitly convert selected traces. `selectedTraceIds` is required and is
 * matched against trace.id (or trace.traceId). No discovery or background work
 * is performed. Every rejected trace produces its own diagnostic entry.
 */
export function convertSelectedTracesToEvalSamples(traces, options = {}) {
  if (!Array.isArray(traces)) throw new TypeError("traces must be an array");
  if (!Array.isArray(options.selectedTraceIds)) {
    throw new TypeError("options.selectedTraceIds must be an array");
  }

  const selected = new Set(options.selectedTraceIds.map(String));
  const samples = [];
  const diagnostics = [];
  for (const trace of traces) {
    const id = trace && (trace.id ?? trace.traceId);
    if (id === undefined || !selected.has(String(id))) continue;
    try {
      samples.push(traceToEvalSample(trace, options));
    } catch (error) {
      diagnostics.push({
        traceId: String(id),
        code: error.code ?? "INVALID_TRACE",
        message: error.message,
      });
    }
  }

  return { samples, diagnostics };
}

export function assertSanitizedTrace(trace) {
  const unsafe = findUnsafeContent(trace);
  if (unsafe) {
    const error = new Error(`trace rejected: ${unsafe.reason} at ${unsafe.location}`);
    error.code = "UNSANITIZED_TRACE";
    error.diagnostic = unsafe;
    throw error;
  }
  return true;
n}

export function isRawCredentialPattern(value) {
  return typeof value === "string" && SECRET_VALUE_PATTERNS.some((pattern) => pattern.test(value));
}

export default convertSelectedTracesToEvalSamples;
